int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const int dx[8] = {-1, -1, -1, 0, 0, 1, 1, 1};
    const int dy[8] = {-1, 0, 1, -1, 1, -1, 0, 1};

    while (true) {
        int w, h;
        cin >> w >> h;
        if (!cin) return 0;
        if (w == 0 && h == 0) break;

        vector<vector<int>> grid(h, vector<int>(w));
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                cin >> grid[i][j];
            }
        }

        int islands = 0;

        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                if (grid[i][j] == 1) {
                    islands++;
                    queue<pair<int,int>> q;
                    q.push({i, j});
                    grid[i][j] = 0;

                    while (!q.empty()) {
                        auto [x, y] = q.front();
                        q.pop();

                        for (int dir = 0; dir < 8; ++dir) {
                            int nx = x + dx[dir];
                            int ny = y + dy[dir];

                            if (0 <= nx && nx < h && 0 <= ny && ny < w && grid[nx][ny] == 1) {
                                grid[nx][ny] = 0;
                                q.push({nx, ny});
                            }
                        }
                    }
                }
            }
        }

        cout << islands << '\n';
    }

    return 0;
}

